 @Test void partialTransferCloseKeepsTransitUntilDifferenceApprovalThenFreezesOriginalLossCost(){
  inCountry(101,()->inventory.inbound(actor,new InventoryApi.Inbound(601,401,501,new BigDecimal("3"),BigDecimal.ZERO,BigDecimal.ZERO,new InventoryApi.Source("LGS_RECEIPT",800,901,"RCV"),date,null,null,new InventoryApi.PurchaseCost(2000,2001,"MXN",new BigDecimal("0.3333"),BigDecimal.ONE,new BigDecimal("3")))));
  seed("INSERT INTO wf_rule(country_id,rule_key,doc_type,name,conditions,nodes,status,effective_from) VALUES(101,'LOSS','TRANSFER_DIFFERENCE','Loss','[]','[{\"seq\":1,\"nodeName\":\"Approve loss\",\"approverType\":\"USER\",\"approverRef\":201,\"mode\":\"ANY\"}]','ACTIVE',clock_timestamp()-interval '1 hour')");
  var t=documents.create(actor,"transfer",Map.of("fromWarehouseId",401,"toWarehouseId",402,"submit",true,"lines",List.of(Map.of("productId",501,"qty",3))),key());long id=((Number)t.get("id")).longValue();t=documents.action(actor,"transfer",id,"ship",Map.of(),key());long line=((Number)((Map<?,?>)((List<?>)t.get("lines")).getFirst()).get("id")).longValue();documents.action(actor,"transfer",id,"receive",Map.of("lines",List.of(Map.of("lineId",line,"qty",1))),key());
  var pending=documents.action(actor,"transfer",id,"close",Map.of("reason","two missing","resolution","LOSS"),key());assertThat(pending).containsEntry("status","PARTIAL_RECEIVED").containsEntry("differenceStatus","PENDING_APPROVAL");assertThat(owner.queryForObject("SELECT sum(qty) FROM inv_transfer_loss",BigDecimal.class)).isNull();assertThatThrownBy(()->documents.action(actor,"transfer",id,"close",Map.of("resolution","LOSS"),key())).extracting("code").isEqualTo("WF_APPROVAL_REQUIRED");
  long task=owner.queryForObject("SELECT t.id FROM wf_task t JOIN wf_instance i ON i.id=t.instance_id AND i.country_id=t.country_id WHERE i.doc_type='TRANSFER_DIFFERENCE' AND t.status='PENDING'",Long.class);workflow.approve(actor,task,"loss verified");String intent=key();var closed=documents.action(actor,"transfer",id,"close",Map.of("resolution","LOSS"),intent);documents.action(actor,"transfer",id,"close",Map.of("resolution","LOSS"),intent);assertThat(closed).containsEntry("status","CLOSED");seed("INSERT INTO sys_user_data_scope(country_id,user_id,scope_type,book_id,granted_by) VALUES(101,201,'BOOK',601,201)");var lossFact=inCountry(101,()->{var a=financialAuth.authorize(actor);var raw=com.hs.jxc.common.db.DbRows.camel(jdbc.queryForMap("SELECT * FROM sys_biz_event WHERE event_type='INV_STOCK_CHANGED' AND source_type='INV_TRANSFER_LOSS'"));return financialSources.stream().filter(p->p.supports("INV_STOCK_CHANGED")).findFirst().orElseThrow().accountingFact(a,"INV_STOCK_CHANGED","INV_TRANSFER_LOSS",((Number)raw.get("sourceId")).longValue(),((Number)raw.get("eventSeq")).intValue(),LocalDate.parse(raw.get("bizDate").toString()),financialJson.readMap(raw.get("payload").toString()));});assertThat(lossFact).containsEntry("sourceDocType","INV_TRANSFER").containsEntry("sourceDocId",id);assertThat(((Map<?,?>)lossFact.get("payload")).get("accountingImpact")).isEqualTo("NONE");assertThat(owner.queryForObject("SELECT sum(qty) FROM inv_transfer_loss",BigDecimal.class)).isEqualByComparingTo("2");assertThat(owner.queryForObject("SELECT sum(on_hand_qty) FROM inv_stock_summary",BigDecimal.class)).isEqualByComparingTo("1");assertThat(owner.queryForObject("SELECT amount FROM cst_cogs WHERE source_type='INV_TRANSFER_LOSS'",BigDecimal.class)).isEqualByComparingTo("0.6667");assertThatThrownBy(()->documents.action(actor,"transfer",id,"receive",Map.of("lines",List.of(Map.of("lineId",line,"qty",1))),key())).extracting("code").isEqualTo("INV_INVALID_STATE");
 }
 @Autowired java.util.List<com.hs.jxc.fin.api.FinancialSourceProvider> financialSources;
