 @Test void stockChangeUsesLineIdentityAndReturnsTheRealDocument(){
  receive(901,"5");seed("insert into sys_user_data_scope(country_id,user_id,scope_type,book_id,granted_by) values(101,201,'BOOK',601,201)");
  var fact=inCountry(101,()->{var a=financialAuth.authorize(actor);var raw=com.hs.jxc.common.db.DbRows.camel(jdbc.queryForMap("select * from sys_biz_event where event_type='INV_STOCK_CHANGED' and source_id=901"));var provider=financialSources.stream().filter(p->p.supports("INV_STOCK_CHANGED")).findFirst().orElseThrow(()->new AssertionError("Missing INV line-identity financial source"));return provider.accountingFact(a,"INV_STOCK_CHANGED","LGS_RECEIPT",901,((Number)raw.get("eventSeq")).intValue(),date,financialJson.readMap(raw.get("payload").toString()));});
  assertThat(fact).containsEntry("bookId",601L).containsEntry("sourceDocType","LGS_RECEIPT").containsEntry("sourceDocId",800L);assertThat((Map<String,Object>)fact.get("payload")).containsEntry("accountingImpact","NONE");
 }

